fn run_blocked<B: Bench>(
    bench: &mut B,
    blocks: u64,
    outer_override: Option<u64>,
    target_seconds: f64,
    inner: u64,
) -> (Histogram<u64>, f64, BlockStats) {
    let mut hist = new_hist();
    let mut dither = Dither::new();
